#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, h;
    cin >> n >> h;
    vector<vector<long long>> dp(n + 1, vector<long long>(n + 1, 0));
    for (int j = 0; j <= n; ++j) {
        dp[0][j] = 1;
    }
    for (int i = 0; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            for (int k = 0; k < i; ++k) {
                dp[i][j] += dp[k][j - 1] * dp[i - 1 - k][j - 1];
            }
        }
    }
    long long result = dp[n][n];
    if (h > 0) {
        result -= dp[n][h - 1];
    }
    cout << result << endl;
    return 0;
}
